export async function openOwnersSearchList(page) {
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Search" }).click();
}

export async function openOwnerDetail(page, ownerHref) {
    await page.locator(`a[href="${ownerHref}"]`).click();
}

export async function findOwnerByLastName(page, lastName) {
    await page.locator("#lastName").fill(lastName);
    await page.getByRole("button", { name: "Find Owner" }).click();
}

export async function openAddPetForm(page) {
    await page.getByRole("button", { name: "Add New Pet" }).click();
}

export async function fillPetIdentityFields(page, name, nickname) {
    await page.locator("#name").fill(name);
    await page.locator("#nickname").fill(nickname);
}

export async function fillPetTypeAndBirthDate(page, typeName, birthDate) {
    await page.getByLabel("Type").selectOption(typeName);
    await page.locator("#birthDate").fill(birthDate);
    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
}

export async function submitPetForm(page) {
    const responsePromise = page.waitForResponse("**/petclinic/api/owners/**/pets**");
    await page.getByRole("button", { name: "Save Pet" }).click();
    return await responsePromise;
}

export async function openPetEditForm(page) {
    await page.getByRole("button", { name: "Edit Pet" }).first().click();
}
